from pathlib import Path
root=Path(__file__).resolve().parents[1]
def edit(path,pairs):
 p=root/path;s=p.read_text()
 for old,new in pairs:
  assert s.count(old)==1, (path,s.count(old),old[:100])
  s=s.replace(old,new)
 p.write_text(s)
